import React from 'react';

import type { PluginProps } from './../../ricos-types/index.js';

import { FileViewer } from '../viewer/file-viewer.js';

export const File: React.FC<PluginProps> = ({ settings = {}, componentData, node }) => {
  return (
    <FileViewer
      nodeId={node.attrs.id}
      componentData={componentData}
      settings={settings}
      isLoading={node.attrs.loading}
      tempDataPlaceHolder={node.attrs.tempData}
    />
  );
};
