import type { ViewerPluginCreator } from './../ricos-types/index.js';

import { DEFAULTS } from './defaults.js';
import type { FilePluginViewerConfig } from './types.js';
import { FILE_UPLOAD_TYPE } from './types.js';
import { nodeViewRenderers } from './viewer/node-view-renderers.js';

export const pluginFileUpload: ViewerPluginCreator<FilePluginViewerConfig> = config => {
  return {
    config: { ...DEFAULTS.configViewer, ...config },
    type: FILE_UPLOAD_TYPE,
    nodeViewRenderers,
  };
};
