import { Attachement } from '@wix/wix-ui-icons-common/lazy';

import type { PluginServices } from './../ricos-plugins/editor-plugins.js';
import type { AddButton } from './../ricos-types/index.js';
import { Node_Type } from './../ricos-types/index.js';
import { INSERT_PLUGIN_BUTTONS, TOOLBARS } from './../editor-common/index.js';

import { INSERT_FILE_BUTTON } from './data-hooks.js';
import { handleFileUpload } from './handle-file-upload.js';
import type { FilePluginEditorConfig } from './types.js';

export const toolbarsToAddIn: (TOOLBARS.MOBILE | TOOLBARS.FOOTER | TOOLBARS.SIDE)[] = [
  TOOLBARS.FOOTER,
  TOOLBARS.SIDE,
  TOOLBARS.MOBILE,
];

export const getAddButtons = (
  config: FilePluginEditorConfig,
  services: PluginServices
): AddButton[] => {
  return [
    {
      id: Node_Type.FILE,
      label: INSERT_PLUGIN_BUTTONS.FILE,
      dataHook: INSERT_FILE_BUTTON,
      icon: Attachement,
      tooltip: 'FileUploadInsertButton_tooltip',
      toolbars: toolbarsToAddIn,
      command: ({ publicCommands, referenceElement }) => {
        handleFileUpload({
          services,
          config,
          publicCommands,
          referenceElement: referenceElement ?? undefined,
        });
        return true;
      },
      menuConfig: {
        tags: 'UploadFile_plugin_search_tags',
      },
    },
  ];
};
