import React from 'react';

import type { NodeViewRenderer, NodeViewRenderers } from './../../ricos-types/index.js';
import { Node_Type } from './../../ricos-types/index.js';

import File from './file.js';

const FileRenderer: NodeViewRenderer = ({ node, ...props }) => {
  return <File key={node.id} node={node} {...props} />;
};

export const nodeViewRenderers: NodeViewRenderers = {
  [Node_Type.FILE]: FileRenderer,
};
